import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import ReportCard from '../../../components/ui/ReportCard/ReportCard';
import { mockUsers, mockOngs, mockAdmins } from '../../../data/mockData';
import styles from './ReportsPage.module.css';

const ReportsPage = () => {
  const totalUsers = mockUsers.length;
  const totalOngs = mockOngs.length;
  const totalAdmins1 = mockAdmins.length;
  const totalAdmins5 = 1; // O próprio Super Admin
  const totalSeals = mockUsers.reduce((sum, user) => sum + user.seals, 0);

  return (
    <ContentWrapper title="Relatórios do Sistema">
      <div className={styles.grid}>
        <ReportCard title="Total de Usuários" value={totalUsers} />
        <ReportCard title="Total de ONGs" value={totalOngs} />
        <ReportCard title="Admins Nv.1" value={totalAdmins1} />
        <ReportCard title="Admins Nv.5" value={totalAdmins5} />
        <ReportCard title="Total de Selos em Circulação" value={totalSeals} />
      </div>
    </ContentWrapper>
  );
};

export default ReportsPage;
